style.css:
@-moz-document url-prefix("chrome://newtab") {
body {
        background: #000 url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="100%" height="100%"><filter id="noise"><feTurbulence type="fractalNoise" baseFrequency="0.8"/></filter><rect width="100%" height="100%" filter="url(%23noise)" opacity="0.1"/></svg>');
        overflow: hidden;
    }
    
    /* Удаляем стандартные элементы */
    .most-visited, .logo, .search-box { display: none !important; }
    
    /* Звезды */
    body::before {
        content: "";
        position: fixed;
        top: 0;
        left: 0;
        width: 200%;
        height: 200%;
        background: 
            radial-gradient(white 1px, transparent 1px),
            radial-gradient(white 1px, transparent 1px);
        background-size: 50px 50px;
        background-position: 0 0, 25px 25px;
        animation: stars 100s linear infinite;
    }
    
    @keyframes stars {
        100% { transform: translate(-25px, -25px); }
    }
}
